import React, { useState, useCallback, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import Navbar from "../components/Navbar";
import Sidebar, { NavItem, NavGroup } from "../components/Sidebar";

const NAV_FEATURES: NavGroup[] = [
  { id: "dashboard", label: "Dashboard", path: "/dashboard", icon: "⊞" },
  {
    id: "users",
    label: "User Management",
    path: "/users",
    icon: "👥",
    children: [
      { id: "users-analytics", label: "Analytics", path: "/users/analytics" },
      { id: "users", label: "Users", path: "/users" },
    ],
  },
  {
    id: "jobs", label: "Job Management", path: "/jobs", icon: "💼",
    children: [
      { id: 'jobs-analytics', label: 'Analytics', path: '/jobs/analytics' },
      { id: 'jobs', label: 'Jobs', path: '/jobs' },
    ],
  },
];

export const AdminLayout: React.FC<React.PropsWithChildren<{}>> = ({
  children,
}) => {
  const [collapsed, setCollapsed] = useState(false);
  const [openTabs, setOpenTabs] = useState<NavItem[]>([]);
  const [isMobile, setIsMobile] = useState(false);
  const [mobileSidebarOpen, setMobileSidebarOpen] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    const mq = window.matchMedia("(max-width: 768px)");
    setIsMobile(mq.matches);
    const handler = (e: MediaQueryListEvent) => {
      setIsMobile(e.matches);
      if (!e.matches) {
        setMobileSidebarOpen(false); // Close mobile drawer if resized to desktop
      }
    };
    mq.addEventListener("change", handler);
    return () => mq.removeEventListener("change", handler);
  }, []);

  const sidebarWidth = isMobile ? 0 : (collapsed ? 56 : 280);
  const navbarHeight = 64;

  const handleNavigate = useCallback((item: NavItem) => {
    setOpenTabs((prev) => {
      const exists = prev.find((t) => t.id === item.id);
      return exists ? prev : [...prev, item];
    });
  }, []);

  const handleCloseTab = useCallback(
    (id: string) => {
      setOpenTabs((prev) => {
        const idx = prev.findIndex((t) => t.id === id);
        const next = prev.filter((t) => t.id !== id);
        if (next.length > 0) {
          navigate(next[Math.max(0, idx - 1)].path);
        } else {
          navigate("/dashboard");
        }
        return next;
      });
    },
    [navigate],
  );

  return (
    <div style={{ minHeight: "100vh", background: "#F9FBFC", position: "relative" }}>
      {/* Drawer backdrop for mobile view */}
      {isMobile && mobileSidebarOpen && (
        <div
          onClick={() => setMobileSidebarOpen(false)}
          style={{
            position: "fixed",
            inset: 0,
            background: "rgba(15,23,42,0.3)",
            backdropFilter: "blur(4px)",
            zIndex: 140,
            animation: "fadeIn 0.2s ease",
          }}
        />
      )}

      <Sidebar
        features={NAV_FEATURES}
        collapsed={collapsed}
        onToggle={() => {
          if (isMobile) {
            setMobileSidebarOpen(false);
          } else {
            setCollapsed((c) => !c);
          }
        }}
        onNavigate={(item) => {
          handleNavigate(item);
          if (isMobile) {
            setMobileSidebarOpen(false);
          }
        }}
        isMobile={isMobile}
        mobileOpen={mobileSidebarOpen}
      />
      <Navbar
        sidebarWidth={sidebarWidth}
        openTabs={openTabs}
        onCloseTab={handleCloseTab}
        isMobile={isMobile}
        onToggleMobileSidebar={() => setMobileSidebarOpen((o) => !o)}
      />
      <main
        style={{
          marginLeft: sidebarWidth,
          marginTop: navbarHeight,
          padding: isMobile ? 16 : 24,
          minHeight: `calc(100vh - ${navbarHeight}px)`,
          boxSizing: "border-box",
          transition: "margin-left 0.25s ease, padding 0.25s ease",
          overflow: "auto",
        }}
      >
        {children}
      </main>

      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; }
          to { opacity: 1; }
        }
      `}</style>
    </div>
  );
};

export default AdminLayout;
